import 'package:isar/isar.dart';

part 'einvoice.g.dart';

/// E-Invoice (Electronic Invoice) for GST compliance.
/// Contains IRN (Invoice Reference Number) generated by IRP.
@collection
class EInvoice {
  Id id = Isar.autoIncrement;

  /// Invoice Reference Number (64-character unique ID from IRP)
  @Index(unique: true)
  String? irn;

  /// Reference to original invoice
  int? invoiceId;
  String invoiceNumber = '';
  DateTime invoiceDate = DateTime.now();

  /// Acknowledgment number from IRP
  String? ackNumber;

  /// Acknowledgment date from IRP
  DateTime? ackDate;

  /// QR code data (base64 encoded)
  String? qrCodeData;

  /// Signed invoice JSON from IRP
  String? signedInvoiceJson;

  /// E-Invoice status: 'pending', 'generated', 'cancelled', 'error'
  String status = 'pending';

  /// Error message if generation failed
  String? errorMessage;

  /// Error code if generation failed
  String? errorCode;

  /// Whether e-invoice is required for this invoice
  bool isRequired = true;

  /// Cancelled reason (if cancelled within 24 hours)
  String? cancelledReason;

  /// Cancelled date
  DateTime? cancelledDate;

  /// Created timestamp
  DateTime createdAt = DateTime.now();

  /// Last updated timestamp
  DateTime? updatedAt;
}